import csv, os, statistics
d = os.path.join(os.environ["PANTHEON_PROJECTS"], "exports/orders")
files = sorted((f for f in os.listdir(d) if f.endswith(".csv")), key=lambda f: os.path.getmtime(os.path.join(d, f)))
print("files:", files[-31:])
today, base = files[-1], files[-31:-1]
read = lambda f: list(csv.DictReader(open(os.path.join(d, f), newline="", encoding="utf-8-sig")))
old = [r for f in base for r in read(f)]; new = read(today)
for col in ["amount", "payment"]:
    if new and col not in new[0]: print(col, "is not in", today); continue
    vals = [r.get(col, "") for r in old]
    try:
        nums = [float(v) for v in vals if v]; med = statistics.median(nums); mad = statistics.median(abs(x - med) for x in nums)
        print(col, "median", med, "MAD", mad)
        for i, r in enumerate(new, 2):
            if r[col] and abs(float(r[col]) - med) > 3 * mad: print("  row", i, list(r.values())[0], r[col])
    except ValueError:
        known = set(vals); print(col, len(known), "known values")
        for v in sorted({r[col] for r in new} - known): print("  new", repr(v), sum(r[col] == v for r in new), "rows")
    if all(vals) and not all(r.get(col) for r in new): print("  blanks", sum(not r.get(col) for r in new))

